require_once __DIR__.'/../includes/functions.php';require_role(['admin']);expire_donations($pdo);
$stats=[];$stats['users']=(int)$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn();$stats['donations']=(int)$pdo->query('SELECT COUNT(*) FROM food_donations')->fetchColumn();$stats['active']=(int)$pdo->query("SELECT COUNT(*) FROM food_donations WHERE status IN ('Active','Partially Collected') AND expiry_at>NOW() AND remaining_quantity>0")->fetchColumn();$stats['expired']=(int)$pdo->query("SELECT COUNT(*) FROM food_donations WHERE status='Expired'")->fetchColumn();$stats['pending']=(int)$pdo->query("SELECT COUNT(*) FROM collection_requests WHERE status='Pending'")->fetchColumn();$stats['completed']=(int)$pdo->query("SELECT COUNT(*) FROM collection_requests WHERE status='Collected'")->fetchColumn();$recent=$pdo->query('SELECT d.id,d.food_name,d.category,d.locality,d.status,d.created_at,u.name donor_name FROM food_donations d JOIN users u ON u.id=d.donor_id ORDER BY d.created_at DESC LIMIT 8')->fetchAll();$trend=$pdo->query('SELECT DATE(created_at) day,COUNT(*) total FROM food_donations WHERE created_at>=DATE_SUB(CURDATE(),INTERVAL 6 DAY) GROUP BY DATE(created_at) ORDER BY day')->fetchAll();$page_title='Admin dashboard | SharePlate';require __DIR__.'/../includes/header.php';?>
<section class="page-hero compact"><div class="container"><p class="eyebrow">Platform overview</p><h1>Administrator dashboard</h1><p>Monitor food sharing activity and keep the community safe.</p><div class="admin-nav"><a href="dashboard.php">Overview</a><a href="users.php">Users</a><a href="donations.php">Donations & reports</a><a href="requests.php">Requests</a></div></div></section><section class="container section"><div class="stats-grid admin-stats"><?php foreach(['users'=>'Registered users','donations'=>'Total donations','active'=>'Active listings','expired'=>'Expired listings','pending'=>'Pending requests','completed'=>'Completed collections'] as $key=>$label):?><article class="stat-card"><strong><?=number_format($stats[$key])?></strong><span><?=e($label)?></span></article><?php endforeach;?></div><div class="admin-chart-card"><div><p class="eyebrow">Last seven days</p><h2>New food listings</h2></div><canvas id="donationChart" height="100" aria-label="New food listings over the last seven days"></canvas></div><h2 class="section-subheading">Recent donation activity</h2><div class="table-wrap"><table><thead><tr><th>Food</th><th>Category</th><th>Locality</th><th>Donor</th><th>Created</th><th>Status</th></tr></thead><tbody><?php foreach($recent as $d):?><tr><td><a href="../food-details.php?id=<?=$d['id']?>"><?=e($d['food_name'])?></a></td><td><?=e($d['category'])?></td><td><?=e($d['locality'])?></td><td><?=e($d['donor_name'])?></td><td><?=e(format_datetime($d['created_at']))?></td><td><?=e($d['status'])?></td></tr><?php endforeach;?></tbody></table></div></section><script src="https://cdn.jsdelivr.net/npm/chart.js"></script><script>const trend=<?=json_encode($trend,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;if(window.Chart){new Chart(document.getElementById('donationChart'),{type:'bar',data:{labels:trend.map(x=>x.day),datasets:[{label:'Listings',data:trend.map(x=>Number(x.total)),backgroundColor:'#237a57',borderRadius:8}]},options:{plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,ticks:{precision:0}}}}});}</script><?php require __DIR__.'/../includes/footer.php';?>